            native_metadata = json.loads((a.ROOT / native_manifest["path"]).read_bytes())
            native_resources = [resource for resource in native_metadata["resourceManifest"]["resources"]
                                if resource.get("resourceName") == "MarieNativeDLL"]
            if len(native_resources) != 1:
                raise ValueError("Current Marie native resource declaration is absent or ambiguous")
            resource = native_resources[0]
            declared_sha = resource["sha256"].lower()
            if resource.get("integrity") != "sha256-" + base64.b64encode(bytes.fromhex(declared_sha)).decode():
                raise ValueError("Current Marie native manifest hash and integrity differ")
            indexed = json.loads((a.ROOT / ".analysis/inputs.json").read_bytes())
            candidates = [source for source in indexed["inputs"] if source.get("sha256", "").lower() == declared_sha
                          and source.get("bytes") == resource["size"] and source["path"].startswith(".analysis/inputs/")]
            original = next((source for source in candidates if valid(source)), None)
            if original is None:
                raise ValueError("No byte-verified retained input matches the current Marie native resource declaration")
            binary = {**original, "declared_sha256": declared_sha, "declared_bytes": resource["size"],
                      "resource": resource, "manifest": native_manifest}
            native_root = a.ROOT / ".analysis/results/native" / binary["sha256"]
            native_path = native_root / "capture.json"
            row["native_input"] = {"acquisition": identity(native_acquisition_path), "manifest": native_manifest,
                                   "deployment_stability": native_stability, "original": binary,
                                   "expected_capture": a.rel(native_path)}
            native = json.loads(native_path.read_bytes())
            if (native.get("input_sha256") != binary["sha256"] or native.get("input_bytes") != binary["bytes"]
                    or not native.get("capture_complete")):
                raise ValueError("Complete current Marie native capture differs")
            outputs = [{**item, "path": a.rel(native_root / item["path"])} for item in native["outputs"]]
            if any(not valid(item) for item in outputs):
                raise ValueError("Current Marie native complete output byte identity differs")
            entrypoints = json.loads((native_root / "entrypoints.json").read_bytes())
            names = {"DeviceInitialize", "DeviceTerminate", "GetMode", "GetDeviceVolume", "GetDeviceMute", "SetDeviceVolume", "SetDeviceMute",
                     "SetMicMonitorEnable", "SetMicMonitorLevel", "SetNodeFFIEvent", "SetLevelMeterEnable", "SetLevelMeterPumpInterval", "GetLevelMeter",
                     "SetMasterSampleRate", "FreeMalloc"}
            exported = [item for item in entrypoints if item["name"] in names]
            if len(exported) != len(names):
                raise ValueError("Current Marie native ABI exports are incomplete")
            rvas = {item["rva"] for item in exported} | {"0x5630", "0x5660", "0x5690", "0x56c0", "0x65f0", "0x6610", "0x4cd0", "0x5d90", "0x3d780", "0x33a50"}
            functions = {}
            for item in native["functions"]:
                if item["rva"] not in rvas:
                    continue
                path = native_root / item["path"]
                record = {"path": a.rel(path), "bytes": path.stat().st_size, "sha256": item["sha256"]}
                if not valid(record):
                    raise ValueError("Complete current Marie function identity differs: " + record["path"])
                functions[item["rva"]] = {"capture": record, **json.loads(path.read_bytes())}
            if set(functions) != rvas:
                raise ValueError("Current Marie complete native function boundaries are absent")
            row["native_capture"] = {"acquisition": identity(native_acquisition_path), "original": binary,
                "receipt": identity(native_path), "outputs": outputs, "exports": exported, "complete_functions": functions,
                **{key: native[key] for key in ("image_base", "ida_version", "hexrays_version", "capture_tool", "functions_total", "functions_captured",
                                               "capture_complete", "all_pseudocode_captured", "failures")},
                "limitations": "Captured current ABI does not establish real device runtime acceptance."}
