            containing = [node for node in class_nodes if node.start_byte <= caller_byte < node.end_byte]
            if not containing: raise ValueError("Customize mounted caller is outside a complete owner class")
            node_region(min(containing, key=lambda node: node.end_byte-node.start_byte), "customize_mounted_owner_class")
            image_symbol = re.search(r'(?:jsx|jsxs)\)\(([\w$]+),\{pid:', body)[1]
            image_body, image_record = binding(image_symbol, "product_image_alias")
            while re.fullmatch(r'[\w$]+', image_body):
                image_body, image_record = binding(image_body, "product_image_producer", image_record["character_start"])
            if not all(token in image_body for token in ("editionId", "layoutId", "img_prods", "svg_prods")):
                raise ValueError("Current complete ProductImage producer is unresolved")
            config_original, config_text = next((source, source_text) for source, source_text in sources if f"productId:{pid}," in source_text)
            config = complete_raw_module(config_text, f"productId:{pid},")
            category_match = re.search(r'productId:' + str(pid) + r',[^{}]{0,1500}?category:"([^"]+)"', config["body"])
            if category_match is None: raise ValueError("Actual DeviceInfo category is unresolved")
            category = category_match[1]
            normalize_to_prd = category in re.findall(r'\.[\w$]+\.([A-Z]+)(?:&&|\?)', image_body)
            row.setdefault("complete_modules", []).append({**config, "original": config_original, "role": "product_configuration"})
            row["product_image"] = {"svg": "isSvg:!0" in body, "edition_zero_fallback": "0!==" in image_body,
                                    "category": category, "normalize_to_prd": normalize_to_prd,
                                    "layout": "prd" if normalize_to_prd else "preserve observed numeric layout"}
            button_symbol = re.search(r'(?:jsx|jsxs)\)\(([\w$]+),\{button:this.props.buttonList', body)[1]
            button_binding, _ = binding(button_symbol, "config_button_connected_owner")
            button_class = re.search(r'\)\(([\w$]+)\)$', button_binding)
            if button_class is None: raise ValueError("ConfigButton Redux class is unresolved")
            matching = [node for node in class_nodes if raw[node.child_by_field_name("name").start_byte:node.child_by_field_name("name").end_byte].decode() == button_class[1]]
            if len(matching) != 1: raise ValueError("ConfigButton complete class is missing/ambiguous")
            node_region(matching[0], "config_button_component")

            # The current button list supplies disabled/line behavior and the
            # 2676/2684 functionList spread; an empty Rust table is not evidence.
            button_tables = []
            for source, source_text in sources:
                if 'buttonKey:"M1"' not in source_text: continue
                module = complete_raw_module(source_text, 'buttonKey:"M1"')
                if "groupList:" not in module["body"]: continue
                group_symbol = re.search(r'groupList:\(\)=>([\w$]+)', module["body"])[1]
                constants = {}
                for match in re.finditer(r'(?<![\w$])([\w$]+)=\[', module["body"]):
                    opening = match.end()-1; stop = javascript_delimited(module["body"], opening)
                    if match[1] == group_symbol: continue
