            if len(button_tables) != 1: raise ValueError("Current controller physical list is missing/ambiguous")
            controls = button_tables[0]
            row["button_controls"] = controls
            list_module = next(item for item in row["complete_modules"] if item["role"] == "physical_button_list")
            list_id = list_module["module_id"]
            list_callers = [(source, source_text, match) for source, source_text in sources
                            for match in re.finditer(r'\.bind\([\w$]+,' + str(list_id) + r'\)', source_text)]
