            if imported is None: raise ValueError("Canvas constant namespace import is unresolved")
            constant_modules = [(source, complete_raw_module(source_text, "cvsH:")) for source, source_text in sources
                                if "cvsH:" in source_text]
            constant_modules = [(source, module) for source, module in constant_modules if module["module_id"] == int(imported[1])]
            if len(constant_modules) != 1: raise ValueError("Actual canvas constants module is missing/ambiguous")
            constants_body = constant_modules[0][1]["body"]
