            if len(lines) != len(controls): raise ValueError("Source callouts do not cover the physical button list")
            row.update({"geometry": geometry, "lines": lines, "button_sides": sides})

            asset_exports = {}
            for source, source_text in sources:
                for match in re.finditer(r'\b(\d+):(?:\([\w$,]*\)=>|[\w$]+=>|function\([\w$,]*\))\{([^{}]{0,1000})\}', source_text):
                    exported = re.search(r'\.p\s*\+\s*["\'](static/media/[^"\']+)["\']', match[2])
                    if exported: asset_exports[int(match[1])] = (source, match, exported[1])
            resource_map, images, mkeys, seen = {}, [], [], set()
            def resource(filename, request, export, mode):
                url = urllib.parse.urljoin(acquired["entry_url"], filename); source = files.get(url)
                if source is None or source.get("http_status") != 200:
                    previous = source; source = a.download(url, receipt_path.parent)
                    row.setdefault("supplemental_acquisition", []).append(source)
                    if source.get("http_status") != 200 or not valid(source): raise ValueError("Official image acquisition failed: " + url)
                    if previous:
                        if (source["sha256"], source["bytes"]) != (previous.get("sha256"), previous.get("bytes")): raise ValueError("Official image differs from retained mounted bytes")
                        source["previous_attempts"] = previous.get("previous_attempts", []) + [{key: value for key, value in previous.items() if key != "previous_attempts"}]
                        acquired["files"][acquired["files"].index(previous)] = source
                    else: acquired["files"].append(source)
