def review_legacy_host_native():
    """Verify current official host files and HID worker/Windows API records."""
    import evidence as e
    import sys
    sys.path.insert(0, str(a.ROOT / "tools/analyzers/python-static"))
    from tree_sitter import Language, Parser
    import tree_sitter_javascript
    parser = Parser(Language(tree_sitter_javascript.language()))
    inspection_path = a.ROOT / ".analysis/results/host-current/inspection.json"
    inspection = json.loads(inspection_path.read_bytes())
    acquisition_path = a.ROOT / inspection["acquisition"]
    acquisition = json.loads(acquisition_path.read_bytes())
    packages = {item["path"]: item for item in acquisition["files"] if item.get("path")}
    members = [item for container in inspection["containers"] for item in container.get("files", [])]
    archives = [item for item in members if item["path"].endswith("/resources/app.asar")]
    if len(archives) != 1 or not valid(archives[0]):
        raise ValueError("Legacy DualLink current official host ASAR is absent/ambiguous")
    archive = archives[0]
    package = packages[archive["container"]]
    if not valid(package):
        raise ValueError("Legacy DualLink official host package bytes differ")
    asar_path = a.ROOT / ".analysis/results/host-current/asar" / archive["sha256"] / "capture.json"
    asar = json.loads(asar_path.read_bytes())
    if asar["input_sha256"] != archive["sha256"] or asar["input_bytes"] != archive["bytes"]:
        raise ValueError("Legacy DualLink host ASAR capture identity differs")
    result = {"acquisition": identity(acquisition_path), "inspection": identity(inspection_path),
        "official_package": package, "asar": archive, "asar_capture": identity(asar_path),
        "asar_unresolved": asar.get("unresolved", []), "complete_original_files": [],
        "target_execution": False, "runtime_acceptance": "unverified"}
    for relative in ("electron/UsbRzDeviceAction.js", "electron/preload.js", "electron/main.js",
                     "electron/modules/mapping_engine/win/index.js", "node_modules/node-rz-hid/nodehid.js",
                     "electron/components/Tab/common.js", "electron/components/Tab/TabManager.js",
                     "electron/components/Tab/TabStore.js", "electron/modules/window_storage/index.js"):
        matches = [item for item in asar["files"] if item["path"].endswith("/" + relative)]
        if len(matches) != 1 or not valid(matches[0]):
            raise ValueError("Legacy DualLink current host source is absent/ambiguous: " + relative)
        source = matches[0]
        body = (a.ROOT / source["path"]).read_bytes()
        with (a.ROOT / archive["path"]).open("rb") as stream:
            stream.seek(source["offset"])
            if stream.read(len(body)) != body:
                raise ValueError("Legacy DualLink host source differs from original ASAR span")
        result["complete_original_files"].append({"relative_to_asar": relative, "original": source,
            "complete_body": body.decode("utf-8"), "body_sha256": hashlib.sha256(body).hexdigest()})
    host_files = {item["relative_to_asar"]: item for item in result["complete_original_files"]}
    result["complete_host_dispatch_owners"] = []

    def host_owner(relative, token, kind, role):
        source = host_files[relative]["original"]
        raw = (a.ROOT / source["path"]).read_bytes()
        matches = list(re.finditer(re.escape(token.encode()), raw))
        if len(matches) != 1:
            raise ValueError("Legacy host action/owner is absent/ambiguous: " + token)
        tree = parser.parse(raw)
        if tree.root_node.has_error:
            raise ValueError("Legacy host source JavaScript grammar failed: " + relative)
        node = tree.root_node.descendant_for_byte_range(matches[0].start(), matches[0].end())
        while node is not None and node.type != kind:
            node = node.parent
        if node is None:
            raise ValueError("Legacy host action complete AST owner is unresolved: " + token)
        record = {"role": role, "original": source, "byte_start": node.start_byte,
            "byte_end": node.end_byte, "syntax": node.type, "body": node.text.decode("utf-8"),
            "body_sha256": hashlib.sha256(node.text).hexdigest()}
        result["complete_host_dispatch_owners"].append(record)
        return raw, tree, node

    for token, role in [('case"getFocusTab"', "selected_host_tab_query"),
                        ('case"getWindowStatus"', "host_window_visibility_query"),
                        ('case D.GET_WINDOW_SERVICE_CLIENTS', "window_service_clients_query"),
                        ('case D.ACTIVE_WINDOW_SERVICE_CLIENT', "window_service_activation_fallthrough"),
                        ('case"focus"', "window_service_activation_dispatch"),
                        ('case"launchAppSimple"', "local_simple_window_launch_and_cleanup"),
                        ('case"resetWindowStorage"', "window_storage_action_dispatch")]:
        host_owner("electron/main.js", token, "switch_case", role)
    for token, role in [("doElectronAction:async", "preload_electron_action_transport"),
                        ("getWindowServiceClients:async", "preload_window_clients_query"),
                        ("activateWindowServiceClient:", "preload_window_activation")]:
        host_owner("electron/preload.js", token, "pair", role)
    common_source = host_files["electron/components/Tab/common.js"]["original"]
    common_raw = (a.ROOT / common_source["path"]).read_bytes()
    common_tree = parser.parse(common_raw)
    for export, binding in (("getFocusingTabInSpecificWindow", "pe"), ("getWindowOfSpecificTab", "ue"), ("getTabByName", "ae")):
        at = common_raw.index((export + ":" + binding).encode())
        resolution = e.javascript_binding(common_raw, common_tree, binding, at)
        if resolution["resolution"] != "declaration":
            raise ValueError("Legacy host current selected-tab export binding differs")
        result["complete_host_dispatch_owners"].append({"role": export, "original": common_source,
            "export_reference_byte": at, "byte_start": resolution["start_byte"], "byte_end": resolution["end_byte"],
            "syntax": resolution["syntax"], "body": resolution["body"], "body_sha256": resolution["sha256"]})
    for relative, names in {
        "electron/components/Tab/TabStore.js": ["getActiveTabOfWindow", "setActiveTabOfWindow", "findTab"],
        "electron/components/Tab/TabManager.js": ["handleChangeActiveTabRequest", "setActiveTabOfWindow"],
    }.items():
        source = host_files[relative]["original"]
        body = (a.ROOT / source["path"]).read_bytes()
        tree = parser.parse(body)
        stack, found = [tree.root_node], {}
        while stack:
            node = stack.pop()
            name = node.child_by_field_name("name") if node.type == "method_definition" else None
            if name is not None and name.text.decode() in names:
                key = name.text.decode()
                if key in found:
                    raise ValueError("Legacy host tab method is ambiguous: " + key)
                found[key] = node
            stack.extend(reversed(node.children))
        if set(names) - found.keys():
            raise ValueError("Legacy host tab method is absent: " + relative)
        for name, node in found.items():
            result["complete_host_dispatch_owners"].append({"role": name, "original": source,
                "byte_start": node.start_byte, "byte_end": node.end_byte, "syntax": node.type,
                "body": node.text.decode("utf-8"), "body_sha256": hashlib.sha256(node.text).hexdigest()})
    matches = [item for item in members if item["path"].endswith("/node-rz-hid/build/Release/HID.node")
               and item["container"] == archive["container"]]
    if len(matches) != 1:
        raise ValueError("Legacy DualLink official host HID native input is absent/ambiguous")
    result["hid_native"] = verify_native_functions(matches[0], {
        "0xcc90": "napi_method_registration", "0x7f40": "napi_send_feature_async",
        "0x7340": "napi_get_feature_async", "0x5280": "async_work_queue",
        "0x4800": "async_operation_worker", "0x50e0": "async_operation_completion_callback",
        "0x17a10": "hid_send_feature_report_HidD_SetFeature",
        "0x17ac0": "hid_get_feature_report_DeviceIoControl", "0x8900": "napi_send_feature_sync",
        "0x7790": "napi_get_feature_sync"})
    result["semantics"] = {
        "host_framing": "UsbRzDeviceAction finds the exact device map entry, then the source container fallback. A90-byte payload with91-byte report length gets a reportId/claimInterface prefix. The default getFeature response removes its leading report ID. Preserve the source truthy reportId selection, including its0 fallback.",
        "mutex_lifecycle": "HID mutex acquisition/send/get/release and source tab-destroy/suspend/app-exit cleanup remain in complete UsbRzDeviceAction/main/preload bodies; a send result does not establish a successful protocol response.",
        "native_write": "NAPI registration maps sendFeatureReport to0x7f40, which queues operation0 through0x5280. Worker0x4800 invokes hid_send_feature_report0x17a10 and Windows HidD_SetFeature; native return/errors propagate through the async result path.",
        "native_read": "NAPI getFeatureReport0x7340 queues operation1; worker0x4800 calls hid_get_feature_report0x17ac0, whose complete body uses DeviceIoControl IOCTL0xB0192 and overlapped completion. Report-ID bytes remain part of the native buffer contract.",
        "focus_query": "getFocusTab reads the named window's browserWindow ID, gets TabStore.windows[id].tabName and finds that tab's frameName. getWindowStatus separately reports visibility/minimization. The selected host tab gate is not the OS active-window state.",
        "window_service": "The preload invokes electronAction and stringifies the returned clients. Host clients enumerate real tabs/windows/webviews; activation focuses the resolved owning window and requests its active tab. TabManager updates TabStore and emits activeTabChanged. The complete source owners preserve force-focus/hibernate branches.",
        "window_storage": "WindowStorage maps values by sender URL. Reads return all truthy matching values as JSON entries; writes notify other non-disposed webContents respecting registered URL listeners. Preload teardown removes storage/tab listeners, while destroyed host contents clear their URL's storage.",
        "limits": "All selected IDA records are reverified against the actual original PE chunks. This retains full disassembly/pseudocode/failures and does not establish the complete native device-event producer or page closure."}
    result["unresolved_chains"] = ["Mapping-engine native device-event producer/type/collection selection must be joined to the exact current product registration and parser branch", "Host dispatch/lifecycle/resource closure beyond the retained files remains required; host package acquisition limitations are not cleared by these verified spans"]
    return result


def compare_global_shortcut_mapping(actual, oracle):
    """Compare every source field while retaining genuine product branches."""
    fields = {"keys", "default_turbo_ids", "turbo_events", "constants"}
    constant_fields = {"SINGLE_STATE_INPUT_ID", "SCROLL_INPUT_ID", "SCROLL_TURBO_DELAY_MS"}
    if (set(actual) != fields or set(actual["constants"]) != constant_fields or not actual["keys"]
            or not actual["default_turbo_ids"] or len(set(actual["default_turbo_ids"])) != len(actual["default_turbo_ids"])
            or set(actual["turbo_events"]) != set(actual["default_turbo_ids"])):
        raise ValueError("Dashboard complete mapping vocabulary is incomplete or ambiguous")
    comparisons = {}
    for pid, expected in oracle.items():
        if set(expected) != fields:
            raise ValueError("Shared mapping oracle has incomplete fields for product " + pid)
        comparisons[pid] = {key: actual[key] == expected[key] for key in actual}
    if not all(comparisons.get("70", {}).values()) or "70" not in comparisons or not all(row["keys"] for row in comparisons.values()):
        raise ValueError("Dashboard complete mapping data differs from the shared typed-table oracle")
    return comparisons


def global_shortcut_default_turbos(audit, source, module):
    """Resolve the default list inside its actual generator, without JS execution."""
    def walk(node):
        yield node
        for child in node.named_children:
            yield from walk(child)
    tree = audit.tree(source)
    generators = []
    for node in walk(tree.root_node):
        if node.type != "assignment_expression" or not module["byte_start"] <= node.start_byte < node.end_byte <= module["byte_end"]:
            continue
        left = node.child_by_field_name("left")
        if left.type == "member_expression" and left.child_by_field_name("object").type == "this" and left.child_by_field_name("property").text == b"generateDefaultTurbos":
            generators.append(node)
    if len(generators) != 1:
        raise ValueError("Dashboard default generator is absent or ambiguous")
    defaults = []
    for node in walk(generators[0].child_by_field_name("right")):
        if node.type == "assignment_expression":
            left, right = node.child_by_field_name("left"), node.child_by_field_name("right")
            if (left.type == "member_expression" and left.child_by_field_name("object").type == "this"
                    and left.child_by_field_name("property").text == b"defaultTurbos"):
                builder = None
                if right.type == "call_expression":
                    function, arguments = right.child_by_field_name("function"), right.child_by_field_name("arguments").named_children
                    if function.type != "member_expression" or function.child_by_field_name("property").text != b"map" or len(arguments) != 1:
                        raise ValueError("Dashboard default list uses an unresolved transform")
                    callback = arguments[0]
                    parameter = callback.child_by_field_name("parameter")
                    body = callback.child_by_field_name("body")
                    if (callback.type != "arrow_function" or parameter is None or body is None or body.type != "call_expression"
                            or body.child_by_field_name("function").type != "identifier"
                            or [child.text for child in body.child_by_field_name("arguments").named_children] != [parameter.text]):
                        raise ValueError("Dashboard default record builder is unresolved")
                    reference = body.child_by_field_name("function")
                    builder = audit.binding("dashboard_default_turbo_builder", source, reference.text.decode(), reference.start_byte)
                    if builder["resolution"] != "declaration":
                        raise ValueError("Dashboard default record builder has no lexical owner")
                    right = function.child_by_field_name("object")
                if right.type != "array":
                    raise ValueError("Dashboard default list is not a complete literal array")
                defaults.append((right, builder))
    if len(defaults) != 1:
        raise ValueError("Dashboard default list is absent or ambiguous inside its generator")
    owner = audit.retain_range("dashboard_default_turbo_generator", source, generators[0].start_byte, generators[0].end_byte, "complete_source_assignment")
    return static_js_literal(defaults[0][0].text.decode()), owner, defaults[0][1]


def validate_shortcut_capture_keys(rows):
    """Require every mounted-recorder field without merging compiler metadata."""
    required = {"name": str, "type": str, "scancode": int, "virtualKey": str, "keyCode": str, "flag": int}
    optional = {"inputID": str, "outputFlag": int, "pageID": str, "HID": str, "modifier": str, "ExtendedKey": str}
    if type(rows) is not list or not rows:
        raise ValueError("Mounted recorder keys must be a complete ordered list")
    for row in rows:
        if type(row) is not dict or not required.keys() <= row.keys() or not row.keys() <= required.keys() | optional.keys():
            raise ValueError("Mounted recorder key fields differ from the complete source schema")
        for name, value in row.items():
            if type(value) is not (required | optional)[name] or (type(value) is int and not 0 <= value < 2**32):
                raise ValueError("Mounted recorder key field has an invalid type or range: " + name)
    return rows


def shortcut_capture_sources(audit, modules, roles):
    """Retain the UI-specific key table and the current DKM producer closure."""
    keys_source = modules[46114][0]
    exported = audit.webpack_export("shortcut_capture_keys", [keys_source], 46114, "Rk")
